### Instruction:
Create a JavaScript program which takes an array of integers as a parameter and reverses the array in-place.

### Input:
[3, 5, 9, 1, 6]

### Response:
function reverseArrayInPlace(nums) {
    let left = 0;
    let right = nums.length - 1;

    while (left < right) {
        let temp = nums[left];
        nums[left] = nums[right];
        nums[right] = temp;

        left++;
        right--;
    }
    return nums;
}

